using System;
using System.Collections.Generic;
using UnityEngine;
using global::InControl;

namespace Framework.Input.Integrations.InControl
{
    /// <summary>
    /// InControlと汎用入力インターフェースを接続する
    /// 入力アダプター。
    ///
    /// ゲーム内の操作識別子とInControlの操作を
    /// 関連付けることで、入力取得処理を共通化する。
    ///
    /// ゲーム固有の操作内容やキー割り当て、
    /// キャラクター制御には依存しない。
    /// </summary>
    /// <typeparam name="TAction">
    /// ゲーム内の操作を識別する列挙型。
    /// </typeparam>
    public sealed class InControlInputAdapter<TAction> :
        IInputProvider<TAction>,
        IDisposable
        where TAction : struct, Enum
    {
        #region Runtime Fields

        /// <summary>
        /// 個別操作を管理する辞書。
        /// </summary>
        private readonly Dictionary<TAction, PlayerAction>
            playerActions =
                new Dictionary<TAction, PlayerAction>();

        /// <summary>
        /// 2軸操作を管理する辞書。
        /// </summary>
        private readonly Dictionary<TAction, PlayerTwoAxisAction>
            twoAxisActions =
                new Dictionary<TAction, PlayerTwoAxisAction>();

        /// <summary>
        /// 初期化が完了しているか。
        /// </summary>
        private bool isInitialized;

        /// <summary>
        /// 入力取得が有効になっているか。
        /// </summary>
        private bool isInputEnabled;

        /// <summary>
        /// 終了処理が実行されているか。
        /// </summary>
        private bool disposed;

        #endregion

        #region Properties

        /// <summary>
        /// Adapterの初期化が完了しているか。
        /// </summary>
        public bool IsInitialized =>
            isInitialized && !disposed;

        /// <summary>
        /// 入力を取得できる状態か。
        /// </summary>
        public bool IsInputEnabled =>
            IsInitialized && isInputEnabled;

        /// <summary>
        /// 登録されている個別操作の数。
        /// </summary>
        public int PlayerActionCount =>
            playerActions.Count;

        /// <summary>
        /// 登録されている2軸操作の数。
        /// </summary>
        public int TwoAxisActionCount =>
            twoAxisActions.Count;

        /// <summary>
        /// 登録されているすべての操作数。
        /// </summary>
        public int ActionCount =>
            PlayerActionCount + TwoAxisActionCount;

        #endregion

        #region Initialization Methods

        /// <summary>
        /// 入力アダプターを初期化する。
        ///
        /// 既に初期化されている場合は何もしない。
        /// 登録済みの操作情報は維持する。
        /// </summary>
        /// <param name="enableInput">
        /// 初期化後に入力を有効にするか
        /// </param>
        public void Initialize(bool enableInput = true)
        {
            ThrowIfDisposed();

            if (isInitialized)
            {
                return;
            }

            isInitialized = true;
            isInputEnabled = enableInput;
        }

        #endregion

        #region Registration Methods

        /// <summary>
        /// 操作識別子とInControlの個別操作を関連付ける。
        ///
        /// 同じ操作識別子の重複登録は許可しない。
        /// </summary>
        /// <param name="action">登録する操作識別子</param>
        /// <param name="playerAction">登録する個別操作</param>
        /// <returns>登録に成功した場合はtrue</returns>
        public bool RegisterAction(
            TAction action,
            PlayerAction playerAction)
        {
            ThrowIfDisposed();

            if (playerAction == null)
            {
                throw new ArgumentNullException(
                    nameof(playerAction));
            }

            // 個別操作と2軸操作の重複を防止する。
            if (HasAction(action))
            {
                return false;
            }

            playerActions.Add(action, playerAction);

            return true;
        }

        /// <summary>
        /// 操作識別子とInControlの2軸操作を関連付ける。
        /// </summary>
        /// <param name="action">登録する操作識別子</param>
        /// <param name="axisAction">登録する2軸操作</param>
        /// <returns>登録に成功した場合はtrue</returns>
        public bool RegisterTwoAxisAction(
            TAction action,
            PlayerTwoAxisAction axisAction)
        {
            ThrowIfDisposed();

            if (axisAction == null)
            {
                throw new ArgumentNullException(
                    nameof(axisAction));
            }

            // 個別操作と2軸操作の重複を防止する。
            if (HasAction(action))
            {
                return false;
            }

            twoAxisActions.Add(action, axisAction);

            return true;
        }

        /// <summary>
        /// 指定された操作の登録を解除する。
        ///
        /// InControl側の操作やキー割り当ては破棄しない。
        /// </summary>
        /// <param name="action">解除する操作識別子</param>
        /// <returns>登録解除に成功した場合はtrue</returns>
        public bool UnregisterAction(TAction action)
        {
            ThrowIfDisposed();

            if (playerActions.Remove(action))
            {
                return true;
            }

            return twoAxisActions.Remove(action);
        }

        /// <summary>
        /// すべての操作の登録を解除する。
        ///
        /// InControl側の操作セットは破棄しない。
        /// </summary>
        public void ClearActions()
        {
            ThrowIfDisposed();

            playerActions.Clear();
            twoAxisActions.Clear();
        }

        #endregion

        #region Action Lookup Methods

        /// <summary>
        /// 指定された操作が登録されているか確認する。
        ///
        /// 入力の有効状態には影響されない。
        /// </summary>
        /// <param name="action">確認する操作識別子</param>
        /// <returns>登録されている場合はtrue</returns>
        public bool HasAction(TAction action)
        {
            if (disposed)
            {
                return false;
            }

            return playerActions.ContainsKey(action) ||
                   twoAxisActions.ContainsKey(action);
        }

        /// <summary>
        /// 操作識別子に対応する個別操作を取得する。
        ///
        /// キーコンフィグなどで利用する。
        /// 入力の有効状態には影響されない。
        /// </summary>
        /// <param name="action">取得する操作識別子</param>
        /// <param name="playerAction">取得された個別操作</param>
        /// <returns>取得に成功した場合はtrue</returns>
        public bool TryGetPlayerAction(
            TAction action,
            out PlayerAction playerAction)
        {
            playerAction = null;

            if (disposed)
            {
                return false;
            }

            return playerActions.TryGetValue(
                action,
                out playerAction);
        }

        /// <summary>
        /// 操作識別子に対応する2軸操作を取得する。
        /// </summary>
        /// <param name="action">取得する操作識別子</param>
        /// <param name="axisAction">取得された2軸操作</param>
        /// <returns>取得に成功した場合はtrue</returns>
        public bool TryGetTwoAxisAction(
            TAction action,
            out PlayerTwoAxisAction axisAction)
        {
            axisAction = null;

            if (disposed)
            {
                return false;
            }

            return twoAxisActions.TryGetValue(
                action,
                out axisAction);
        }

        #endregion

        #region Button Methods

        /// <summary>
        /// 指定されたボタンの押下状態を取得する。
        /// </summary>
        /// <param name="action">取得する操作識別子</param>
        /// <returns>押されている場合はtrue</returns>
        public bool GetButton(TAction action)
        {
            if (!IsInputEnabled)
            {
                return false;
            }

            return TryGetPlayerAction(
                       action,
                       out PlayerAction playerAction) &&
                   playerAction.IsPressed;
        }

        /// <summary>
        /// 指定されたボタンが押された瞬間を取得する。
        /// </summary>
        /// <param name="action">取得する操作識別子</param>
        /// <returns>押されたフレームの場合はtrue</returns>
        public bool GetButtonDown(TAction action)
        {
            if (!IsInputEnabled)
            {
                return false;
            }

            return TryGetPlayerAction(
                       action,
                       out PlayerAction playerAction) &&
                   playerAction.WasPressed;
        }

        /// <summary>
        /// 指定されたボタンが離された瞬間を取得する。
        /// </summary>
        /// <param name="action">取得する操作識別子</param>
        /// <returns>離されたフレームの場合はtrue</returns>
        public bool GetButtonUp(TAction action)
        {
            if (!IsInputEnabled)
            {
                return false;
            }

            return TryGetPlayerAction(
                       action,
                       out PlayerAction playerAction) &&
                   playerAction.WasReleased;
        }

        #endregion

        #region Axis Methods

        /// <summary>
        /// 指定された操作の1軸入力値を取得する。
        /// </summary>
        /// <param name="action">取得する操作識別子</param>
        /// <returns>
        /// -1～1の入力値。
        /// 無効または未登録の場合は0。
        /// </returns>
        public float GetAxis(TAction action)
        {
            if (!IsInputEnabled)
            {
                return 0f;
            }

            if (!TryGetPlayerAction(
                    action,
                    out PlayerAction playerAction))
            {
                return 0f;
            }

            return SanitizeAxis(playerAction.Value);
        }

        /// <summary>
        /// 指定された操作の2軸入力値を取得する。
        /// </summary>
        /// <param name="action">取得する操作識別子</param>
        /// <returns>
        /// 各成分が-1～1の入力ベクトル。
        /// 無効または未登録の場合はVector2.zero。
        /// </returns>
        public Vector2 GetVector2(TAction action)
        {
            if (!IsInputEnabled)
            {
                return Vector2.zero;
            }

            if (!TryGetTwoAxisAction(
                    action,
                    out PlayerTwoAxisAction axisAction))
            {
                return Vector2.zero;
            }

            // InControlから2軸入力を取得する。
            Vector2 value = axisAction.Value;

            // 不正な値を除去し、入力範囲を保証する。
            return new Vector2(
                SanitizeAxis(value.x),
                SanitizeAxis(value.y));
        }

        #endregion

        #region Control Methods

        /// <summary>
        /// 入力取得の有効状態を設定する。
        ///
        /// 操作の登録情報やキー割り当ては維持する。
        /// InControl側の操作セットには影響を与えない。
        /// </summary>
        /// <param name="enabled">
        /// 入力取得を有効にする場合はtrue
        /// </param>
        public void SetInputEnabled(bool enabled)
        {
            ThrowIfDisposed();

            if (!isInitialized)
            {
                return;
            }

            isInputEnabled = enabled;
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// 入力値を検証し、-1～1の範囲へ制限する。
        /// </summary>
        /// <param name="value">検証する入力値</param>
        /// <returns>補正された入力値</returns>
        private static float SanitizeAxis(float value)
        {
            if (float.IsNaN(value) ||
                float.IsInfinity(value))
            {
                return 0f;
            }

            return Mathf.Clamp(value, -1f, 1f);
        }

        /// <summary>
        /// 終了処理済みの場合に例外を発生させる。
        /// </summary>
        private void ThrowIfDisposed()
        {
            if (disposed)
            {
                throw new ObjectDisposedException(
                    GetType().Name);
            }
        }

        #endregion

        #region Dispose Methods

        /// <summary>
        /// 入力アダプターの終了処理を行う。
        ///
        /// 登録情報を解除し、入力取得を無効にする。
        /// InControl側の操作セットは破棄しない。
        /// </summary>
        public void Dispose()
        {
            if (disposed)
            {
                return;
            }

            playerActions.Clear();
            twoAxisActions.Clear();

            isInputEnabled = false;
            isInitialized = false;
            disposed = true;
        }

        #endregion
    }
}
